import React from 'react';
import { Modal, Button, Carousel } from 'react-bootstrap';
import './ProjectModal.css';

const ProjectModal = ({ show, handleClose, project }) => {
    if (!project) return null;

    return (
        <Modal show={show} onHide={handleClose} size="lg" centered className="project-modal">
            <Modal.Header closeButton className="modal-header-custom">
                <Modal.Title>{project.title}</Modal.Title>
            </Modal.Header>

            <Modal.Body>
                {/* Carousel de Imagens */}
                {project.images && project.images.length > 0 && (
                    <Carousel className="mb-4">
                        {project.images.map((image, index) => (
                            <Carousel.Item key={index}>
                                <img
                                    className="d-block w-100"
                                    src={image}
                                    alt={`${project.title} - Imagem ${index + 1}`}
                                    style={{ maxHeight: '400px', objectFit: 'contain' }}
                                />
                            </Carousel.Item>
                        ))}
                    </Carousel>
                )}

                <div className="row">
                    <div className="col-lg-8">
                        {/* Descrição */}
                        <div className="project-description mb-4">
                            <h5>Descrição</h5>
                            <p>{project.description}</p>
                        </div>

                        {/* Tecnologias */}
                        {project.technologies && (
                            <div className="project-technologies mb-4">
                                <h5>Tecnologias Utilizadas</h5>
                                <div className="tech-tags">
                                    {project.technologies.map((tech, index) => (
                                        <span key={index} className="tech-tag">{tech}</span>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>

                    <div className="col-lg-4">
                        {/* Informações do Projeto */}
                        <div className="project-info">
                            <h5>Informações do Projeto</h5>
                            <ul>
                                <li><strong>Categoria:</strong>
                                    {project.category === 'filter-app' && ' React Native'}
                                    {project.category === 'filter-card' && ' Node.js'}
                                    {project.category === 'filter-web' && ' Web'}
                                </li>
                                <li><strong>Status:</strong> Completo</li>
                                <li><strong>Data:</strong> 2024-2025</li>
                                <li><strong>URL:</strong> Projeto Privado</li>
                            </ul>
                        </div>
                    </div>
                </div>
            </Modal.Body>

            <Modal.Footer>
                <Button variant="secondary" onClick={handleClose}>
                    Fechar
                </Button>
                <Button variant="primary" href={project.details} target="_blank">
                    <i className="bx bx-link-external"></i> Ver Detalhes
                </Button>
            </Modal.Footer>
        </Modal>
    );
};

export default ProjectModal;
